68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
75	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
79	
80	    /**
81	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
82	     * line here so audit trails can be captured independently of application logging.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        rejectMissingOrBlankFields(ownerFieldsDto);
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        owner.setAddress(normalizeAddress(owner.getAddress()));
136	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
137	        owner.setEmail(normalizeEmail(owner.getEmail()));
138	        if (owner.getRegistrationDate() == null) {
139	            owner.setRegistrationDate(LocalDate.now());
140	        }
141	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
142	        rejectDuplicateTelephone(owner.getTelephone());
143	        rejectDailyLimitReached(owner.getRegistrationDate());
144	        rejectCityAtCapacity(owner.getCity());
145	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
146	            assignHousehold(owner);
147	        } else {
148	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
149	        }
150	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
151	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
152	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
153	        this.clinicService.saveOwner(owner);
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
156	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
174	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
175	        this.clinicService.saveOwner(currentOwner);
176	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
177	    }
