243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    /**
257	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
258	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
259	     *
260	     * @param fields the submitted owner fields
261	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
262	     *                                        {@code null} or blank, or if address is blank after
263	     *                                        normalization
264	     */
265	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
266	        List<String> missing = new ArrayList<>();
267	        if (isBlank(fields.getFirstName())) {
268	            missing.add("firstName");
269	        }
270	        if (isBlank(fields.getLastName())) {
271	            missing.add("lastName");
272	        }
273	        if (isBlank(normalizeAddress(fields.getAddress()))) {
274	            missing.add("address");
275	        }
276	        if (isBlank(fields.getCity())) {
277	            missing.add("city");
278	        }
279	        if (isBlank(fields.getTelephone())) {
280	            missing.add("telephone");
281	        }
282	        if (!missing.isEmpty()) {
283	            throw new RequiredFieldsMissingException(missing);
284	        }
285	    }
286	
287	    private boolean isBlank(String value) {
288	        return value == null || value.isBlank();
289	    }
290	
291	    /**
292	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
293	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
294	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
295	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
296	     *
297	     * @param telephone the raw telephone value from the request
298	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
299	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
300	     */
301	    private String normalizeTelephone(String telephone) {
302	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
303	        String digits;
304	        if (cleaned.startsWith("+")) {
305	            digits = cleaned.substring(1);
306	        } else {
307	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
308	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
309	            digits = "61" + national;
310	        }
311	        if (!digits.matches("[0-9]{8,15}")) {
312	            throw new InvalidTelephoneException(cleaned);
313	        }
314	        return "+" + digits;
315	    }
316	
317	    /**
318	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
319	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
320	     * lower-cased.
321	     *
322	     * @param email the raw email value from the request, or {@code null} if omitted
323	     * @return the lower-cased email, or {@code null} if none was supplied
324	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
325	     */
326	    private String normalizeEmail(String email) {
327	        if (email == null) {
328	            return null;
329	        }
330	        String trimmed = email.strip();
331	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
332	            throw new InvalidEmailException(email);
333	        }
334	        return trimmed.toLowerCase(Locale.ROOT);
335	    }
336	
337	    /**
338	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
339	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
340	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
341	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
342	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
343	     *
344	     * @param address the raw address value from the request (may be {@code null})
345	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
346	     */
347	    private String normalizeAddress(String address) {
348	        if (address == null) {
349	            return "";
350	        }
351	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
352	        if (collapsed.isEmpty()) {
353	            return "";
354	        }
355	        String[] tokens = collapsed.split(" ");
356	        StringBuilder sb = new StringBuilder(collapsed.length());
357	        for (int i = 0; i < tokens.length; i++) {
358	            if (i > 0) {
359	                sb.append(' ');
360	            }
361	            sb.append(expandAddressAbbreviation(tokens[i]));
362	        }
363	        return sb.toString();
364	    }
365	
366	    /**
367	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
368	     * returns the token unchanged when it is not a recognised abbreviation.
369	     *
370	     * @param token an upper-cased whole-word address token
371	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
372	     */
373	    private String expandAddressAbbreviation(String token) {
374	        return switch (token) {
375	            case "ST" -> "STREET";
376	            case "RD" -> "ROAD";
377	            case "AVE" -> "AVENUE";
378	            default -> token;
379	        };
380	    }
381	
382	    /**
383	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
384	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
385	     *
386	     * @param telephone the normalized (E.164) telephone of the owner being created
387	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
388	     */
389	    /**
390	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
391	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
392	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
393	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
394	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
395	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
396	     *
397	     * @param city the owner's city
398	     * @param lastName the owner's last name
399	     * @return the assigned customer code
400	     */
401	    private String generateCustomerCode(String city, String lastName) {
402	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
403	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
404	        int sequence = (int) this.clinicService.findAllOwners().stream()
405	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
406	            .count() + 1;
407	        return String.format("%s-%s-%04d", city3, last3, sequence);
408	    }
409	
410	    /**
411	     * Counts how many existing owners already share the given first name and last name, compared
412	     * case-insensitively. The count is taken before the new owner is persisted, so it excludes the
413	     * owner being created.
414	     *
415	     * @param firstName the first name of the owner being created
416	     * @param lastName the last name of the owner being created
417	     * @return the number of existing owners with the same first and last name (case-insensitively)
418	     */
419	    private int countNamesakes(String firstName, String lastName) {
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
422	                && lastName.equalsIgnoreCase(existing.getLastName()))
423	            .count();
424	    }
425	
426	    /**
427	     * The maximum number of owners permitted in a single city. A create request whose city already
428	     * holds this many owners is rejected.
429	     */
430	    private static final int CITY_OWNER_LIMIT = 50;
431	
432	    /**
433	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
434	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
435	     * differing only in the casing of their city share one capacity pool. The count is taken before the
436	     * new owner is persisted, so it excludes the owner being created.
437	     *
438	     * @param city the city of the owner being created
439	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
440	     */
441	    private void rejectCityAtCapacity(String city) {
442	        long existing = this.clinicService.findAllOwners().stream()
443	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
444	            .count();
445	        if (existing >= CITY_OWNER_LIMIT) {
446	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
447	        }
448	    }
449	
450	    /**
451	     * The maximum number of owners permitted to be created in a single day. A create request whose
452	     * registration date already holds this many owners is rejected.
453	     */
454	    private static final int DAILY_OWNER_LIMIT = 100;
455	
456	    /**
457	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
458	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
459	     * persisted, so it excludes the owner being created.
460	     *
461	     * @param registrationDate the registration date of the owner being created
462	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
463	     */
464	    /**
465	     * Adjusts an effective registration date so that it always falls on a business day. When the given
466	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
467	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
468	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
469	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
470	     * business-day-adjusted date.
471	     *
472	     * @param date the effective registration date, supplied or defaulted
473	     * @return the same date when it is a weekday, otherwise the next Monday
474	     */
475	    private LocalDate rollToBusinessDay(LocalDate date) {
476	        DayOfWeek day = date.getDayOfWeek();
477	        if (day == DayOfWeek.SATURDAY) {
478	            return date.plusDays(2);
479	        }
480	        if (day == DayOfWeek.SUNDAY) {
481	            return date.plusDays(1);
482	        }
483	        return date;
484	    }
485	
486	    /**
487	     * The number of owners that must already exist for a given day before a further create is flagged as a
488	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
489	     * the created owner carries {@code bulkSignupWarning = true}.
490	     */
491	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
492	
493	    /**
494	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
495	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
496	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
497	     * the daily create-limit rule's accumulation path.
498	     *
499	     * @param registrationDate the registration date of the owner being created
500	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
501	     */
502	    private boolean isBulkSignupDay(LocalDate registrationDate) {
503	        long existing = this.clinicService.findAllOwners().stream()
504	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
505	            .count();
506	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
507	    }
508	
509	    private void rejectDailyLimitReached(LocalDate registrationDate) {
510	        long existing = this.clinicService.findAllOwners().stream()
511	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
512	            .count();
513	        if (existing >= DAILY_OWNER_LIMIT) {
514	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
515	        }
516	    }
517	
518	    private void rejectDuplicateTelephone(String telephone) {
519	        boolean taken = this.clinicService.findAllOwners().stream()
520	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
521	        if (taken) {
522	            throw new DuplicateTelephoneException(telephone);
523	        }
524	    }
525	
526	    /**
527	     * Rejects a create request whose owner shares both last name and address with an existing owner.
528	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
529	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
530	     * differing case) still count as the same household.
531	     *
532	     * @param lastName the last name of the owner being created
533	     * @param address the address of the owner being created
534	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
535	     */
536	    private void rejectDuplicateHousehold(String lastName, String address) {
537	        String normalizedLastName = normalizeForComparison(lastName);
538	        String normalizedAddress = normalizeForComparison(address);
539	        boolean taken = this.clinicService.findAllOwners().stream()
540	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
541	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
542	        if (taken) {
543	            throw new DuplicateHouseholdException(lastName, address);
544	        }
545	    }
546	
547	    /**
548	     * Assigns the owner being created into a shared household. When at least one existing owner has the
549	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
550	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
551	     * reused when present; otherwise a deterministic id derived from the household's last name and address
552	     * is minted, so independently created members of the same household converge on one value. When no
553	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
554	     *
555	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
556	     */
557	    private void assignHousehold(Owner owner) {
558	        String normalizedLastName = normalizeForComparison(owner.getLastName());
559	        String normalizedAddress = normalizeForComparison(owner.getAddress());
560	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
561	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
562	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
563	            .toList();
564	        if (housemates.isEmpty()) {
565	            return;
566	        }
567	        String householdId = housemates.stream()
568	            .map(Owner::getHouseholdId)
569	            .filter(id -> id != null && !id.isBlank())
570	            .findFirst()
571	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
572	        owner.setHouseholdId(householdId);
573	        for (Owner housemate : housemates) {
574	            if (!householdId.equals(housemate.getHouseholdId())) {
575	                housemate.setHouseholdId(householdId);
576	                this.clinicService.saveOwner(housemate);
577	            }
578	        }
579	    }
580	
581	    /**
582	     * Derives a stable household identifier from the normalized last name and address of a household, as
583	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
584	     * deterministic, so any owner independently joining the same household computes the same identifier.
585	     *
586	     * @param normalizedLastName the household's last name, already normalized for comparison
587	     * @param normalizedAddress the household's address, already normalized for comparison
588	     * @return a stable, shareable household identifier
589	     */
590	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
591	        String key = normalizedLastName + "|" + normalizedAddress;
592	        try {
593	            byte[] digest = MessageDigest.getInstance("SHA-256")
594	                .digest(key.getBytes(StandardCharsets.UTF_8));
595	            StringBuilder sb = new StringBuilder(digest.length * 2);
596	            for (byte b : digest) {
597	                sb.append(String.format("%02x", b));
598	            }
599	            return sb.substring(0, 16);
600	        } catch (NoSuchAlgorithmException e) {
601	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
602	        }
603	    }
604	
605	    /**
606	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
607	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
608	     * lower-cased.
609	     *
610	     * @param value the raw value to normalize (may be {@code null})
611	     * @return the normalized value, or an empty string when {@code value} is {@code null}
612	     */
613	    private String normalizeForComparison(String value) {
614	        if (value == null) {
615	            return "";
616	        }
617	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
618	    }
619	}
