76	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
77	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
78	        problemDetail.setType(URI.create(url.toString()));
79	        problemDetail.setTitle(e.getClass().getSimpleName());
80	        problemDetail.setDetail(detail);
81	        problemDetail.setProperty("timestamp", Instant.now());
82	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
83	        return problemDetail;
