246	    /**
247	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a telephone
248	     * number whose normalized value is already used by another owner.
249	     *
250	     * @param e The {@link DuplicateTelephoneException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
253	     */
254	    @ExceptionHandler(DuplicateTelephoneException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
257	        HttpStatus status = HttpStatus.CONFLICT;
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
259	        detail.setProperty("errors", List.of("telephone"));
260	        logger.debug("Duplicate telephone at {} {}: {}",
261	            request.getMethod(),
262	            request.getRequestURI(),
263	            e.getMessage());
264	        return ResponseEntity.status(status).body(detail);
265	    }
266	
267	    /**
268	     * Handles {@link DuplicateHouseholdException} raised when a create request supplies an owner
269	     * whose last name and address (compared case-insensitively with collapsed whitespace) already
270	     * belong to an existing owner, and the request did not opt in via {@code sharesHousehold}.
271	     *
272	     * @param e The {@link DuplicateHouseholdException} to be handled
273	     * @param request {@link HttpServletRequest} object referring to the current request.
274	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
275	     */
276	    @ExceptionHandler(DuplicateHouseholdException.class)
277	    @ResponseBody
278	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
279	        HttpStatus status = HttpStatus.CONFLICT;
280	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
281	        detail.setProperty("errors", List.of("lastName", "address"));
282	        logger.debug("Duplicate household at {} {}: {}",
283	            request.getMethod(),
284	            request.getRequestURI(),
285	            e.getMessage());
286	        return ResponseEntity.status(status).body(detail);
287	    }
288	
289	    /**
290	     * Handles {@link CityOwnerLimitExceededException} raised when a create request supplies an owner
291	     * whose city (compared case-insensitively) already contains the maximum permitted number of owners.
292	     *
293	     * @param e The {@link CityOwnerLimitExceededException} to be handled
294	     * @param request {@link HttpServletRequest} object referring to the current request.
295	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
296	     */
297	    @ExceptionHandler(CityOwnerLimitExceededException.class)
298	    @ResponseBody
299	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
300	        HttpStatus status = HttpStatus.CONFLICT;
301	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
302	        detail.setProperty("errors", List.of("city"));
303	        logger.debug("City at capacity at {} {}: {}",
304	            request.getMethod(),
305	            request.getRequestURI(),
306	            e.getMessage());
307	        return ResponseEntity.status(status).body(detail);
308	    }
309	
310	    /**
311	     * Handles {@link DailyOwnerLimitExceededException} raised when a create request would exceed the
312	     * maximum number of owners permitted to be created in a single day (compared by
313	     * {@code registrationDate}).
314	     *
315	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
316	     * @param request {@link HttpServletRequest} object referring to the current request.
317	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
318	     */
319	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
320	    @ResponseBody
321	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
322	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
323	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
324	        detail.setProperty("errors", List.of("registrationDate"));
325	        logger.debug("Daily owner limit reached at {} {}: {}",
326	            request.getMethod(),
327	            request.getRequestURI(),
328	            e.getMessage());
329	        return ResponseEntity.status(status).body(detail);
330	    }
